const fs = require("node:fs");
const path = require("node:path");

const PROJECT = "C:\\Users\\edmem\\kodely-prod";

function loadEnv() {
  const raw = fs.readFileSync(path.join(PROJECT, ".env"), "utf8");
  for (const line of raw.split(/\r?\n/)) {
    const m = line.match(/^\s*([A-Za-z0-9_]+)\s*=\s*(.*)$/);
    if (!m) continue;
    let v = m[2].trim();
    if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) {
      v = v.slice(1, -1);
    }
    process.env[m[1]] = v;
  }
}

let pass = 0;
let fail = 0;
function ok(cond, label, extra) {
  if (cond) {
    pass++;
    console.log(`  PASS  ${label}${extra ? ` — ${extra}` : ""}`);
  } else {
    fail++;
    console.log(`  FAIL  ${label}${extra ? ` — ${extra}` : ""}`);
  }
}
function eq(actual, expected, label) {
  ok(actual === expected, label, `got ${JSON.stringify(actual)}, want ${JSON.stringify(expected)}`);
}
function section(name) {
  console.log(`\n=== ${name} ===`);
}
function summary() {
  console.log(`\n---- ${pass} passed, ${fail} failed ----`);
  return fail;
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

module.exports = { PROJECT, loadEnv, ok, eq, section, summary, sleep, counts: () => ({ pass, fail }) };

const { loadEnv, ok, eq, section, summary } = require("./common");
loadEnv();

const F = require("./build/flags");
const { db } = require("./build/db");

const created = new Set();

async function putRow(key, enabled, rolloutPct) {
  await db.featureFlag.upsert({
    where: { key },
    create: { key, enabled, rolloutPct, description: "test", updatedBy: "t1" },
    update: { enabled, rolloutPct },
  });
  created.add(key);
  F.invalidateFlagCache();
}

async function clearRow(key) {
  await db.featureFlag.deleteMany({ where: { key } });
  F.invalidateFlagCache();
}

async function main() {
  const pre = await db.featureFlag.findMany();
  console.log(`table has ${pre.length} row(s) before the run: ${pre.map((r) => r.key).join(", ") || "(none)"}`);

  // ─────────────────────────────────────────────────────────────────────
  section("A1. no row anywhere -> declared whenUnset (per flag)");
  await db.featureFlag.deleteMany({ where: { key: { in: F.FLAG_KEYS } } });
  F.invalidateFlagCache();
  for (const key of F.FLAG_KEYS) {
    const want = F.FLAG_SPECS[key].whenUnset;
    eq(await F.isEnabled(key, "user-a"), want, `${key} unset -> whenUnset`);
    eq(await F.isEnabled(key, null), want, `${key} unset, anonymous -> whenUnset`);
  }
  ok(
    F.FLAG_SPECS[F.FLAGS.generation].whenUnset === true &&
      F.FLAG_SPECS[F.FLAGS.sdkEngine].whenUnset === false,
    "whenUnset genuinely differs per flag (generation true, sdkEngine false)",
  );

  // ─────────────────────────────────────────────────────────────────────
  section("A2. enabled / disabled / rolloutPct edges");
  const K = F.FLAGS.generation;

  await putRow(K, true, 100);
  eq(await F.isEnabled(K, "user-a"), true, "enabled=true pct=100 -> true");
  eq(await F.isEnabled(K, null), true, "enabled=true pct=100, anonymous -> true");

  await putRow(K, false, 100);
  eq(await F.isEnabled(K, "user-a"), false, "enabled=false pct=100 -> false (pct ignored when off)");

  await putRow(K, false, 0);
  eq(await F.isEnabled(K, "user-a"), false, "enabled=false pct=0 -> false");

  await putRow(K, true, 0);
  eq(await F.isEnabled(K, "user-a"), false, "enabled=true pct=0 -> false");

  await putRow(K, true, 50);
  eq(await F.isEnabled(K, null), false, "enabled=true pct=50, anonymous -> false (no stable bucket)");
  eq(await F.isEnabled(K, undefined), false, "enabled=true pct=50, undefined userId -> false");
  eq(await F.isEnabled(K, ""), false, "enabled=true pct=50, empty userId -> false");

  // pct=50 must agree with the pure bucket function for every id
  let mismatch = 0;
  for (let i = 0; i < 3000; i++) {
    const id = `usr_${i}`;
    const want = F.rolloutBucket(id, K) < 50;
    if ((await F.isEnabled(K, id)) !== want) mismatch++;
  }
  eq(mismatch, 0, "isEnabled at 50% agrees with rolloutBucket()<50 for 3000 ids");

  // out-of-range stored value (schema allows any Int) must not misbehave
  await putRow(K, true, 250);
  eq(await F.isEnabled(K, "user-a"), true, "stored pct=250 (>100) -> true, not a modulo surprise");
  await putRow(K, true, -5);
  eq(await F.isEnabled(K, "user-a"), false, "stored pct=-5 (<0) -> false");

  // ─────────────────────────────────────────────────────────────────────
  section("A3. selected fraction tracks rolloutPct");
  const N = 20000;
  for (const pct of [1, 10, 25, 50, 75, 99]) {
    await putRow(K, true, pct);
    let on = 0;
    for (let i = 0; i < N; i++) if (await F.isEnabled(K, `usr_${i}`)) on++;
    const actual = (on / N) * 100;
    ok(Math.abs(actual - pct) < 1.5, `pct=${pct} selects ~${pct}%`, `actual ${actual.toFixed(2)}%`);
  }

  // ─────────────────────────────────────────────────────────────────────
  section("B. bucketing is STABLE per (userId, key)");
  await putRow(K, true, 50);
  const ids = Array.from({ length: 5000 }, (_, i) => `cmg${i.toString(36)}xk0000user${i}`);

  const first = new Map();
  for (const id of ids) first.set(id, await F.isEnabled(K, id));

  // same process, same cache
  let flips = 0;
  for (let round = 0; round < 3; round++) {
    for (const id of ids) if ((await F.isEnabled(K, id)) !== first.get(id)) flips++;
  }
  eq(flips, 0, "5000 ids x 3 more calls, same cached snapshot -> 0 flips");

  // across a cache refresh (new DB read)
  F.invalidateFlagCache();
  flips = 0;
  for (const id of ids) if ((await F.isEnabled(K, id)) !== first.get(id)) flips++;
  eq(flips, 0, "after invalidateFlagCache() + re-read -> 0 flips");

  // across a "process restart": drop the module from require cache and reload
  for (const k of Object.keys(require.cache)) {
    if (k.includes("build") && k.endsWith("flags.js")) delete require.cache[k];
  }
  const F2 = require("./build/flags");
  ok(F2 !== F, "reloaded a fresh copy of the module (simulated cold process)");
  flips = 0;
  for (const id of ids) if ((await F2.isEnabled(K, id)) !== first.get(id)) flips++;
  eq(flips, 0, "fresh module instance, cold cache -> 0 flips (no hidden per-process state)");

  // the bucket function itself
  let bflips = 0;
  for (const id of ids) {
    const b = F.rolloutBucket(id, K);
    if (F.rolloutBucket(id, K) !== b || F2.rolloutBucket(id, K) !== b) bflips++;
  }
  eq(bflips, 0, "rolloutBucket() is pure and stable across module instances");

  // ─────────────────────────────────────────────────────────────────────
  section("C. two flags at 50% must NOT pick the same half");
  const M = 40000;
  const bigIds = Array.from({ length: M }, (_, i) => `cmg${i.toString(36)}xk0000user${i}`);
  const kA = F.FLAGS.generation;
  const kB = F.FLAGS.publishing;

  let a = 0,
    b = 0,
    both = 0;
  for (const id of bigIds) {
    const inA = F.rolloutBucket(id, kA) < 50;
    const inB = F.rolloutBucket(id, kB) < 50;
    if (inA) a++;
    if (inB) b++;
    if (inA && inB) both++;
  }
  const pA = a / M,
    pB = b / M,
    pAB = both / M;
  const phi = (pAB - pA * pB) / Math.sqrt(pA * (1 - pA) * pB * (1 - pB));
  ok(Math.abs(pA - 0.5) < 0.01, "flag A at 50% selects ~half", `${(pA * 100).toFixed(2)}%`);
  ok(Math.abs(pB - 0.5) < 0.01, "flag B at 50% selects ~half", `${(pB * 100).toFixed(2)}%`);
  ok(
    Math.abs(pAB - 0.25) < 0.01,
    "overlap is ~25% (independent), NOT ~50% (identical cohort)",
    `${(pAB * 100).toFixed(2)}%`,
  );
  ok(Math.abs(phi) < 0.02, "phi correlation between the two flags ~ 0", `phi=${phi.toFixed(4)}`);

  // contrast: what it would look like if the key were NOT mixed in
  const { createHash } = require("node:crypto");
  const idOnly = (id) => createHash("sha256").update(id).digest().readUInt32BE(0) % 100;
  let bothIfBuggy = 0;
  for (const id of bigIds) if (idOnly(id) < 50) bothIfBuggy++;
  ok(
    Math.abs(both / M - bothIfBuggy / M) > 0.2,
    "contrast: hashing the id alone would put 100% of arm A also in arm B",
    `key-mixed overlap ${(pAB * 100).toFixed(1)}% vs id-only overlap 50.0%`,
  );

  // all five other flag pairs too
  let worstPhi = 0;
  const keys = F.FLAG_KEYS;
  for (let i = 0; i < keys.length; i++) {
    for (let j = i + 1; j < keys.length; j++) {
      let x = 0,
        y = 0,
        xy = 0;
      const n = 20000;
      for (let t = 0; t < n; t++) {
        const id = bigIds[t];
        const inX = F.rolloutBucket(id, keys[i]) < 50;
        const inY = F.rolloutBucket(id, keys[j]) < 50;
        if (inX) x++;
        if (inY) y++;
        if (inX && inY) xy++;
      }
      const px = x / n,
        py = y / n,
        pxy = xy / n;
      const p = (pxy - px * py) / Math.sqrt(px * (1 - px) * py * (1 - py));
      worstPhi = Math.max(worstPhi, Math.abs(p));
    }
  }
  ok(worstPhi < 0.03, "all 15 flag pairs decorrelated", `worst |phi| = ${worstPhi.toFixed(4)}`);

  // ─────────────────────────────────────────────────────────────────────
  section("C2. bucket distribution is uniform over 0..99");
  const H = new Array(100).fill(0);
  const n = 200000;
  for (let i = 0; i < n; i++) H[F.rolloutBucket(`cmg${i.toString(36)}user${i}`, kA)]++;
  const exp = n / 100;
  const chi = H.reduce((s, o) => s + ((o - exp) * (o - exp)) / exp, 0);
  // df=99: 5% critical value ~123.2, 0.1% ~148.2
  ok(chi < 148, "chi-square over 100 buckets within tolerance (df=99)", `chi2=${chi.toFixed(1)}`);
  const minB = Math.min(...H),
    maxB = Math.max(...H);
  ok(minB > exp * 0.9 && maxB < exp * 1.1, "no bucket off by >10%", `min=${minB} max=${maxB} exp=${exp}`);

  // sequential cuid-like ids must not clump (the failure mode of id.length/charCodeAt)
  const seq = Array.from({ length: 2000 }, (_, i) => `cmgz9q${(1000000 + i).toString(36)}0001abcd`);
  let seqOn = 0;
  for (const id of seq) if (F.rolloutBucket(id, kA) < 10) seqOn++;
  ok(
    Math.abs(seqOn / seq.length - 0.1) < 0.03,
    "2000 ids created back-to-back still split ~10% at pct=10 (no timestamp-prefix clumping)",
    `${((seqOn / seq.length) * 100).toFixed(1)}%`,
  );

  await db.featureFlag.deleteMany({ where: { key: { in: [...created] } } });
  await db.$disconnect();
  return summary();
}

main().then((f) => process.exit(f ? 1 : 0)).catch((e) => {
  console.error(e);
  process.exit(1);
});

