const F = require("./build/flags");

const K = F.FLAGS.generation;
const KP = F.FLAGS.promptEnhance;
const KS = F.FLAGS.sdkEngine;
const TTL = F.FLAG_CACHE_TTL_MS;

const testKeys = [K, KP, KS, F.FLAGS.publishing, F.FLAGS.signups, F.FLAGS.rewards];

async function put(key, enabled, rolloutPct = 100) {
  await realDb.featureFlag.upsert({
    where: { key },
    create: { key, enabled, rolloutPct, description: "test", updatedBy: "t2" },
    update: { enabled, rolloutPct },
  });
}

/** Replace the db module export so lib/flags.ts talks to our stub. */
function useDb(stub) {
  dbMod.db = stub;
}
const breakDb = (msg = "ECONNREFUSED 127.0.0.1:5432") =>
  useDb({
    featureFlag: {
      findMany: async () => {
        throw new Error(msg);
      },
    },
  });

function freshFlags() {
  for (const k of Object.keys(require.cache)) {
    if (k.replace(/\\/g, "/").endsWith("build/flags.js")) delete require.cache[k];
  }
  return require("./build/flags");
}

async function main() {
  const silence = console.error;
  console.error = () => {};

  // ─────────────────────────────────────────────────────────────────────
  section(`D. cache TTL (${TTL}ms): a DB flip lands within the TTL, not before, not never`);
  await put(K, true, 100);
  useDb(realDb);
  F.invalidateFlagCache();

  eq(await F.isEnabled(K, "u1"), true, "warm the cache: reads true");
  const t0 = Date.now();

  // flip it in the DB behind the module's back — no invalidateFlagCache()
  await put(K, false, 100);
  eq(await F.isEnabled(K, "u1"), false === false && (await F.isEnabled(K, "u1")), "");

  let flippedAt = null;
  const samples = [];
  while (Date.now() - t0 < TTL * 2) {
    const v = await F.isEnabled(K, "u1");
    const dt = Date.now() - t0;
    samples.push([dt, v]);
    if (v === false && flippedAt === null) flippedAt = dt;
    await sleep(200);
  }
  const beforeTtl = samples.filter(([dt]) => dt < TTL - 500);
  ok(
    beforeTtl.every(([, v]) => v === true),
    "value stays CACHED (true) for the whole TTL window",
    `${beforeTtl.length} samples in the first ${TTL - 500}ms all true`,
  );
  ok(flippedAt !== null, "the DB change is eventually observed without any invalidation");
  ok(
    flippedAt !== null && flippedAt >= TTL - 300 && flippedAt <= TTL + 1500,
    `observed at ~one TTL`,
    `flipped at ${flippedAt}ms (TTL=${TTL}ms)`,
  );

  // explicit invalidation is immediate (this is what the admin action does)
  await put(K, true, 100);
  const beforeInvalidate = await F.isEnabled(K, "u1");
  F.invalidateFlagCache();
  const afterInvalidate = await F.isEnabled(K, "u1");
  eq(beforeInvalidate, false, "still cached-false right after the DB write");
  eq(afterInvalidate, true, "invalidateFlagCache() -> immediate, no TTL wait");

  // ─────────────────────────────────────────────────────────────────────
  section("E. single-flight: concurrent checks share ONE query");
  let queries = 0;
  useDb({
    featureFlag: {
      findMany: async () => {
        queries++;
        await sleep(50);
        return [{ key: K, enabled: true, rolloutPct: 100 }];
      },
    },
  });
  F.invalidateFlagCache();
  await Promise.all(Array.from({ length: 100 }, () => F.isEnabled(K, "u1")));
  eq(queries, 1, "100 concurrent isEnabled() calls on a cold cache -> 1 query");
  queries = 0;
  await Promise.all(Array.from({ length: 100 }, () => F.isEnabled(K, "u1")));
  eq(queries, 0, "100 more calls inside the TTL -> 0 queries");

  // ─────────────────────────────────────────────────────────────────────
  section("F. fail-safe: COLD process, database unreachable");
  const Fc = freshFlags();
  breakDb();
  for (const key of F.FLAG_KEYS) {
    const spec = F.FLAG_SPECS[key];
    eq(
      await Fc.isEnabled(key, "u1"),
      spec.whenUnavailable,
      `${key} -> declared whenUnavailable (${spec.whenUnavailable ? "OPEN" : "CLOSED"})`,
    );
  }
  ok(
    F.FLAG_KEYS.filter((k) => F.FLAG_SPECS[k].kind === "kill").every(
      (k) => F.FLAG_SPECS[k].whenUnavailable === false,
    ),
    "every kill switch fails CLOSED (a kill switch that fails open is useless)",
  );
  eq(F.FLAG_SPECS[KP].whenUnavailable, true, "prompt_enhance (shipped 100% gate) fails OPEN");
  eq(F.FLAG_SPECS[KS].whenUnavailable, false, "sdk_engine fails CLOSED (closed = known-good engine)");

  // backoff: a broken DB must not be hammered once per check
  let attempts = 0;
  useDb({
    featureFlag: {
      findMany: async () => {
        attempts++;
        throw new Error("down");
      },
    },
  });
  const Fb = freshFlags();
  for (let i = 0; i < 200; i++) await Fb.isEnabled(K, "u1");
  ok(attempts <= 2, "200 checks against a dead DB -> at most 2 queries (error backoff)", `${attempts}`);

  // ─────────────────────────────────────────────────────────────────────
  section("G. fail-safe: WARM process, database dies (stale-if-error)");
  // last-known-good must differ from whenUnavailable in BOTH directions,
  // otherwise the test proves nothing.
  await put(KS, true, 100); // sdk_engine ON  (whenUnavailable = false)
  await put(KP, false, 100); // prompt_enhance OFF (whenUnavailable = true)
  await put(K, false, 100); // generation kill engaged
  const Fw = freshFlags();
  useDb(realDb);
  eq(await Fw.isEnabled(KS, "u1"), true, "warm: sdk_engine reads true from DB");
  eq(await Fw.isEnabled(KP, "u1"), false, "warm: prompt_enhance reads false from DB");
  eq(await Fw.isEnabled(K, "u1"), false, "warm: generation kill reads false from DB");

  breakDb();
  await sleep(TTL + 500); // let the snapshot go stale so it must re-read and fail
  eq(await Fw.isEnabled(KS, "u1"), true, "DB down: sdk_engine STILL true (stale beats whenUnavailable=false)");
  eq(await Fw.isEnabled(KP, "u1"), false, "DB down: prompt_enhance STILL false (stale beats whenUnavailable=true)");
  eq(await Fw.isEnabled(K, "u1"), false, "DB down: the engaged kill switch STAYS engaged");

  // recovery
  useDb(realDb);
  await put(K, true, 100);
  await sleep(2500); // clear the error backoff window
  eq(await Fw.isEnabled(K, "u1"), true, "DB back: fresh value is picked up again");

  // ─────────────────────────────────────────────────────────────────────
  section("H. invalidateFlagCache() vs a read that was already in flight");
  // Simulates the admin process: a request is mid-refresh when setFlag()
  // commits and invalidates. The in-flight query started BEFORE the write, so
  // it can only return the pre-write value.
  await put(K, true, 100);
  const Fr = freshFlags();
  let release;
  const gate = new Promise((r) => (release = r));
  useDb({
    featureFlag: {
      findMany: async () => {
        await gate;
        return [{ key: K, enabled: true, rolloutPct: 100 }]; // pre-write value
      },
    },
  });
  const inflight = Fr.isEnabled(K, "u1"); // starts the refresh
  await sleep(20);
  // meanwhile: the write commits, then setFlag() invalidates
  useDb({
    featureFlag: {
      findMany: async () => [{ key: K, enabled: false, rolloutPct: 100 }], // post-write value
    },
  });
  Fr.invalidateFlagCache();
  release();
  await inflight;
  const afterRace = await Fr.isEnabled(K, "u1");
  ok(
    afterRace === false,
    "a refresh started before invalidateFlagCache() must NOT repopulate the cache",
    afterRace === false ? "post-write value served" : "STALE pre-write value served for a full TTL",
  );

  console.error = silence;
  useDb(realDb);
  await realDb.featureFlag.deleteMany({ where: { key: { in: testKeys } } });
  const left = await realDb.featureFlag.findMany();
  console.log(`\nrows left in FeatureFlag after cleanup: ${left.length}`);
  await realDb.$disconnect();
  return summary();
}

main()
  .then((f) => process.exit(f ? 1 : 0))
  .catch((e) => {
    console.error(e);
    process.exit(1);
  });

