const { loadEnv, ok, eq, section, summary, sleep } = require("./common");
loadEnv();

const { db } = require("./build/db");
const F = require("./build/flags");

const ORPHAN = "zz.retired_switch";
const GEN = F.FLAGS.generation;
const SDK = F.FLAGS.sdkEngine;

async function main() {
  await db.featureFlag.deleteMany({ where: { key: { in: [...F.FLAG_KEYS, ORPHAN] } } });

  section("I. seedFlags(): create-only, never clobbers an operator");
  const n1 = await F.seedFlags("alice@kodely.io");
  eq(n1, F.FLAG_KEYS.length, `seeds one row per flag (${F.FLAG_KEYS.length})`);
  const seeded = await db.featureFlag.findMany();
  eq(seeded.length, F.FLAG_KEYS.length, "rows really exist in the table");
  ok(
    seeded.every((r) => r.enabled === F.FLAG_SPECS[r.key].whenUnset),
    "each row seeded at its declared steady state",
    seeded.map((r) => `${r.key}=${r.enabled}`).join(" "),
  );
  ok(
    seeded.every((r) => r.description === F.FLAG_SPECS[r.key].description && r.updatedBy === "alice@kodely.io"),
    "description + updatedBy written from code",
  );

  // an operator kills generation, then someone re-runs the seeder
  await F.setFlag(GEN, { enabled: false }, "bob@kodely.io");
  const n2 = await F.seedFlags("carol@kodely.io");
  eq(n2, 0, "second seedFlags() creates nothing");
  const afterReseed = await db.featureFlag.findUnique({ where: { key: GEN } });
  eq(afterReseed.enabled, false, "re-seeding does NOT undo a kill an operator just performed");
  eq(afterReseed.updatedBy, "bob@kodely.io", "and does not steal the audit trail");

  section("J. setFlag(): partial patch, clamping, validation, audit");
  await F.setFlag(GEN, { rolloutPct: 40 }, "dave@kodely.io");
  let row = await db.featureFlag.findUnique({ where: { key: GEN } });
  eq(row.rolloutPct, 40, "rollout patch sets the percentage");
  eq(row.enabled, false, "...and leaves `enabled` alone");

  await F.setFlag(GEN, { enabled: true }, "erin@kodely.io");
  row = await db.featureFlag.findUnique({ where: { key: GEN } });
  eq(row.enabled, true, "enable patch sets enabled");
  eq(row.rolloutPct, 40, "...and does NOT commit a stale percentage from the form");

  await F.setFlag(GEN, { rolloutPct: 500 }, "erin@kodely.io");
  eq((await db.featureFlag.findUnique({ where: { key: GEN } })).rolloutPct, 100, "500 clamps to 100");
  await F.setFlag(GEN, { rolloutPct: -3 }, "erin@kodely.io");
  eq((await db.featureFlag.findUnique({ where: { key: GEN } })).rolloutPct, 0, "-3 clamps to 0");
  eq(F.clampRolloutPct(Number.NaN), 100, "clampRolloutPct(NaN) -> 100");
  eq(F.clampRolloutPct(33.6), 34, "clampRolloutPct rounds");

  let threw = null;
  try {
    await F.setFlag("publish_enabled", { enabled: false }, "mallory@evil.example");
  } catch (e) {
    threw = e.message;
  }
  ok(threw && threw.includes("Unknown flag key"), "setFlag rejects a key outside FLAGS", threw);
  eq(
    await db.featureFlag.count({ where: { key: "publish_enabled" } }),
    0,
    "...and wrote nothing (a Server Action is a public endpoint)",
  );

  // description is code-owned
  await db.featureFlag.update({ where: { key: GEN }, data: { description: "stale hand-edit" } });
  await F.setFlag(GEN, { enabled: true }, "erin@kodely.io");
  eq(
    (await db.featureFlag.findUnique({ where: { key: GEN } })).description,
    F.FLAG_SPECS[GEN].description,
    "setFlag rewrites description from FLAG_SPECS",
  );

  // audit trail
  const before = await db.featureFlag.findUnique({ where: { key: GEN } });
  await sleep(1100);
  await F.setFlag(GEN, { enabled: false }, "frank@kodely.io");
  const after = await db.featureFlag.findUnique({ where: { key: GEN } });
  eq(after.updatedBy, "frank@kodely.io", "updatedBy records who");
  ok(after.updatedAt > before.updatedAt, "updatedAt moves forward on every save", `${before.updatedAt.toISOString()} -> ${after.updatedAt.toISOString()}`);

  // setFlag drops the cache, so the writing process sees its own change at once
  await F.setFlag(GEN, { enabled: true, rolloutPct: 100 }, "erin@kodely.io");
  eq(await F.isEnabled(GEN, "u1"), true, "isEnabled() reflects the write immediately (no TTL wait)");
  await F.setFlag(GEN, { enabled: false }, "erin@kodely.io");
  eq(await F.isEnabled(GEN, "u1"), false, "...and the kill lands immediately too");

  // create path for a flag with no row
  await db.featureFlag.delete({ where: { key: SDK } });
  await F.setFlag(SDK, { rolloutPct: 25 }, "grace@kodely.io");
  const created = await db.featureFlag.findUnique({ where: { key: SDK } });
  eq(created.rolloutPct, 25, "setFlag creates a missing row");
  eq(created.enabled, F.FLAG_SPECS[SDK].whenUnset, "...with `enabled` defaulted from whenUnset, not from the client");

  section("K. listFlags(): declaration order, code defaults, orphans");
  await db.featureFlag.create({
    data: { key: ORPHAN, enabled: true, rolloutPct: 70, description: "left behind", updatedBy: "old@kodely.io" },
  });
  await db.featureFlag.delete({ where: { key: F.FLAGS.rewards } });

  const list = await F.listFlags();
  const known = list.filter((f) => f.known);
  const orphans = list.filter((f) => !f.known);
  eq(known.length, F.FLAG_KEYS.length, "every code flag listed");
  ok(
    known.every((f, i) => f.key === F.FLAG_KEYS[i]),
    "listed in FLAGS declaration order (kill switches first)",
    known.map((f) => f.key).join(" | "),
  );
  eq(orphans.length, 1, "the stored key that code no longer knows about is surfaced");
  eq(orphans[0].key, ORPHAN, "orphan identified by key");
  eq(list[list.length - 1].key, ORPHAN, "orphans sort after known flags");
  ok(list.every((f) => f.known === F.isFlagKey(f.key)), "known flag matches isFlagKey()");

  const rewardsView = known.find((f) => f.key === F.FLAGS.rewards);
  eq(rewardsView.stored, false, "a flag with no row is marked stored=false");
  eq(rewardsView.enabled, F.FLAG_SPECS[F.FLAGS.rewards].whenUnset, "...and shows the code default in force");
  eq(rewardsView.updatedAt, null, "...with no 'last changed'");
  const genView = known.find((f) => f.key === GEN);
  eq(genView.stored, true, "a stored flag is marked stored=true");
  eq(genView.updatedBy, "erin@kodely.io", "list carries WHO changed it");
  ok(genView.updatedAt instanceof Date, "list carries WHEN it changed", genView.updatedAt.toISOString());
  ok(genView.spec !== null && orphans[0].spec === null, "spec present for known flags, null for orphans");

  section("L. deleteOrphanFlag()");
  let liveThrew = null;
  try {
    await F.deleteOrphanFlag(GEN);
  } catch (e) {
    liveThrew = e.message;
  }
  ok(liveThrew && liveThrew.includes("Refusing to delete a live flag"), "refuses to delete a live flag", liveThrew);
  eq(await db.featureFlag.count({ where: { key: GEN } }), 1, "...and the row survives");
  await F.deleteOrphanFlag(ORPHAN);
  eq(await db.featureFlag.count({ where: { key: ORPHAN } }), 0, "deletes the orphan row");

  await db.featureFlag.deleteMany({ where: { key: { in: [...F.FLAG_KEYS, ORPHAN] } } });
  const left = await db.featureFlag.findMany();
  console.log(`\nrows left in FeatureFlag after cleanup: ${left.length}`);
  await db.$disconnect();
  return summary();
}

main()
  .then((f) => process.exit(f ? 1 : 0))
  .catch((e) => {
    console.error(e);
    process.exit(1);
  });

