const { loadEnv } = require("./common");
loadEnv();
const { randomBytes, createHash } = require("node:crypto");
const { db } = require("./build/db");

const EMAIL = "zz-flags-verify-admin@example.invalid";

async function main() {
  const mode = process.argv[2];
  if (mode === "down") {
    const u = await db.user.findUnique({ where: { email: EMAIL } });
    if (u) {
      await db.session.deleteMany({ where: { userId: u.id } });
      await db.user.delete({ where: { id: u.id } });
    }
    const F = require("./build/flags");
    const del = await db.featureFlag.deleteMany({ where: { key: { in: F.FLAG_KEYS } } });
    const left = await db.featureFlag.findMany();
    console.log(`cleaned user+sessions, deleted ${del.count} flag row(s); rows left: ${left.length}`);
    await db.$disconnect();
    return;
  }

  const user = await db.user.upsert({
    where: { email: EMAIL },
    create: { email: EMAIL, role: "ADMIN", name: "Flags Verify" },
    update: { role: "ADMIN" },
  });
  const token = randomBytes(32).toString("base64url");
  await db.session.create({
    data: {
      userId: user.id,
      tokenHash: createHash("sha256").update(token).digest("hex"),
      expiresAt: new Date(Date.now() + 3600_000),
    },
  });
  console.log(JSON.stringify({ email: EMAIL, userId: user.id, token }));
  await db.$disconnect();
}
main();

